// === Tab: mySketch ===
const TOTAL = 1000;
let points = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSL, 100);
	background(100);
	noStroke();

	for(var i = 0; i < TOTAL; i++){
		points.push({
			pos: createVector(width/2, height/2),
			dir: random(TWO_PI),
			size: random(0.5, 5),
			color: {
				h: random(10, 13),//yellow
				s: random(60, 100),
				l: 50
			}
		});
	}
}

function draw() {
	var time = millis()/1000;
	for(var i = 0; i < TOTAL; i++){
		var point = points[i];

		point.dir += noise(point.pos.x, point.pos.y, time)-0.477;

		var mouseAngle = atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-point.pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-point.pos.x);
		point.dir += (mouseAngle - point.dir) * 0.05;

		point.size *= 0.99;
		if(point.size < 2){
			point.size = random(2, 5);
			point.pos.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-50, 50);
			point.pos.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-50, 50);
		}

		point.pos.x += cos(point.dir) / (point.size + 2.5) * 10;
		point.pos.y += sin(point.dir) / (point.size + 2.5) * 10;

		//trick 5
		var bri = (noise(point.pos.x/30, point.pos.y/30, time*2+i*0.005)-0.3) * (140-point.size*20);
		fill(point.color.h, point.color.s, point.color.l + bri);
		circle(point.pos.x, point.pos.y, point.size);
	}
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
